def icon(name: str, size: int = 24, label: str = "") -> Markup:
    a11y = f'role="img" aria-label="{label}"' if label else 'aria-hidden="true" focusable="false"'
    return Markup(
        f'<svg class="icon" width="{size}" height="{size}" viewBox="0 0 256 256" fill="currentColor" {a11y}>'
        f"{_PATHS[name]}</svg>"
    )
